/* Optional full CVDICT lookup. No API key or third-party runtime dependency.
 * HSK and ERP results remain the primary, immediate source of definitions.
 * 122k+ CVDICT records live in small, licensed static shards generated by
 * scripts/build-cvdict-index.mjs; only relevant indexes/entry shards are fetched.
 */
(function (root) {
  "use strict";
  var BASE = "./data/dictionary/cvdict-v1/";
  var requests = Object.create(null), manifestRequest = null;
  var disabled = false;
  var LIMIT = 36;

  function normalizeVietnamese(value) {
    return String(value || "").toLowerCase().normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d")
      .replace(/[^a-z0-9]+/g, " ").trim();
  }
  function normalizePinyin(value) {
    return String(value || "").toLowerCase().replace(/u:/g, "v")
      .replace(/[üǖǘǚǜ]/g, "v").normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "").replace(/[1-5]/g, "")
      .replace(/[^a-z]/g, "");
  }
  function tonePinyin(value) {
    var tones = {
      a: ["ā","á","ǎ","à"], e: ["ē","é","ě","è"],
      i: ["ī","í","ǐ","ì"], o: ["ō","ó","ǒ","ò"],
      u: ["ū","ú","ǔ","ù"], "ü": ["ǖ","ǘ","ǚ","ǜ"]
    };
    return String(value || "").replace(/([a-züv:]+)([1-5])/gi, function(full, original, tone) {
      var syllable = original.toLowerCase().replace(/u:/g, "ü").replace(/v/g, "ü");
      if (tone === "5") return syllable;
      var index = syllable.search(/[ae]/);
      if (index < 0) index = syllable.indexOf("ou") >= 0 ? syllable.indexOf("o") : -1;
      if (index < 0) for (var i = syllable.length-1; i >= 0; i--) {
        if (/[iouü]/.test(syllable[i])) { index=i; break; }
      }
      if (index < 0) return syllable;
      return syllable.slice(0,index) + tones[syllable[index]][Number(tone)-1] + syllable.slice(index+1);
    });
  }
  function fetchJson(path) {
    if (!requests[path]) {
      requests[path] = root.fetch(BASE + path, { cache: "force-cache" }).then(function(response) {
        if (!response.ok) throw new Error("Dictionary shard HTTP " + response.status);
        return response.json();
      }).catch(function(error) { delete requests[path]; throw error; });
    }
    return requests[path];
  }
  function manifest() {
    if (disabled) return Promise.resolve(null);
    if (!manifestRequest) manifestRequest = fetchJson("manifest.json").then(function(data) {
      if (!data || data.version !== 1 || data.entryCount < 100000 ||
          data.entryShards !== 128 || data.hanShards !== 64) {
        throw new Error("Invalid CVDICT manifest");
      }
      return data;
    }).catch(function() { disabled = true; return null; });
    return manifestRequest;
  }
  function indexByName(name) { return fetchJson("index/" + name + ".json"); }
  function addIds(output, seen, incoming, max) {
    if (!incoming) return;
    for (var i = 0; i < incoming.length && output.length < max; i++) {
      var id = incoming[i];
      if (Number.isInteger(id) && id >= 0 && !seen.has(id)) {
        seen.add(id);
        output.push(id);
      }
    }
  }
  function prefixIds(index, needle, max) {
    var ids = [], seen = new Set();
    addIds(ids, seen, index[needle], max);
    if (ids.length >= max) return ids;
    var keys = Object.keys(index).filter(function(k) { return k !== needle && k.indexOf(needle) === 0; });
    keys.sort(function(a,b) { return a.length - b.length || a.localeCompare(b); });
    for (var i = 0; i < keys.length && ids.length < max; i++) addIds(ids, seen, index[keys[i]], max);
    return ids;
  }
  function uniqueChars(value) {
    return Array.from(new Set(Array.from(value).filter(function(ch) { return /[\u3400-\u9fff\u{20000}-\u{2fa1f}]/u.test(ch); })));
  }
  function chineseIds(query) {
    var chars = uniqueChars(query);
    if (!chars.length) return Promise.resolve([]);
    var lead = chars[0], bucket = (lead.codePointAt(0) % 64).toString(16).padStart(2, "0");
    return indexByName("han-" + bucket).then(function(index) {
      var ids = prefixIds(index, query, LIMIT);
      var seen = new Set(ids);
      addIds(ids, seen, index[lead], LIMIT);
      return ids;
    });
  }
  function pinyinIds(query) {
    var normalized = normalizePinyin(query);
    if (!normalized || !/^[a-z]/.test(normalized)) return Promise.resolve([]);
    return indexByName("py-" + normalized[0]).then(function(index) {
      return prefixIds(index, normalized, LIMIT);
    });
  }
  function vietnameseIds(query) {
    var tokens = normalizeVietnamese(query).split(" ").filter(function(w) { return w.length >= 2; });
    if (!tokens.length || tokens.length > 7) return Promise.resolve([]);
    return Promise.all(tokens.map(function(token) {
      return indexByName("vi-" + token[0]).then(function(index) {
        return prefixIds(index, token, tokens.length > 1 ? 10000 : 140);
      });
    })).then(function(groups) {
      if (!groups.length) return [];
      groups.sort(function(a,b) { return a.length - b.length; });
      var ids = groups[0];
      for (var i = 1; i < groups.length; i++) {
        var allowed = new Set(groups[i]);
        ids = ids.filter(function(id) { return allowed.has(id); });
      }
      return ids.slice(0, LIMIT);
    });
  }
  function resolveRows(ids) {
    var unique = Array.from(new Set(ids)).slice(0, 90);
    return Promise.all(unique.map(function(id) {
      var shard = (id % 128).toString(16).padStart(2, "0");
      return fetchJson("entries/" + shard + ".json").then(function(rows) {
        return rows[Math.floor(id / 128)] || null;
      });
    })).then(function(rows) { return rows.filter(Boolean); });
  }
  function score(row, query) {
    var hanzi = row[0], trad = row[1];
    var py = normalizePinyin(row[2]), qpy = normalizePinyin(query);
    var meaning = normalizeVietnamese(row[3]), qvi = normalizeVietnamese(query);
    if (hanzi === query || trad === query) return 0;
    if (qpy && py === qpy) return 1;
    if ((hanzi.indexOf(query) === 0 || trad.indexOf(query) === 0) && query) return 2;
    if (qpy && py.indexOf(qpy) === 0) return 3;
    if (qvi && meaning === qvi) return 4;
    if (qvi && (meaning.indexOf(qvi) === 0 || meaning.indexOf("; " + qvi) >= 0)) return 5;
    if (qvi && meaning.indexOf(qvi) >= 0) return 6;
    if (hanzi.indexOf(query) >= 0 || trad.indexOf(query) >= 0) return 7;
    return 99;
  }
  function lookup(query) {
    query = String(query || "").trim();
    if (!query || query.length > 70) return Promise.resolve([]);
    var han = /[\u3400-\u9fff\u{20000}-\u{2fa1f}]/u.test(query);
    if (!han && normalizePinyin(query).length < 2) return Promise.resolve([]);
    return manifest().then(function(ready) {
      if (!ready) return [];
      var ids = han ? [chineseIds(query)] : [pinyinIds(query), vietnameseIds(query)];
      return Promise.all(ids).then(function(groups) {
        return resolveRows([].concat.apply([], groups));
      }).then(function(rows) {
        return rows.map(function(row) { return { row: row, relevance: score(row, query) }; })
          .filter(function(item) { return item.relevance !== 99; })
          .sort(function(a,b) { return a.relevance - b.relevance || a.row[0].length - b.row[0].length; })
          .slice(0, 40).map(function(item) {
            var row = item.row;
            return {
              hanzi: row[0], traditional: row[1], pinyin: tonePinyin(row[2]),
              meanings: { hsk: [], erp: [row[3]] }, examples: { hsk: [], erp: [] },
              pos: "", hskLevels: [], sources: ["cvdict"], cvdictReference: true
            };
          });
      });
    }).catch(function(error) {
      if (root.console && root.console.warn) root.console.warn("CVDICT lookup unavailable; local dictionary remains active:", error);
      return [];
    });
  }
  root.VDuckieExpandedDictionary = Object.freeze({
    lookup: lookup, manifest: manifest, normalizePinyin: normalizePinyin,
    normalizeVietnamese: normalizeVietnamese, tonePinyin: tonePinyin
  });
})(window);
